// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.provider/** * NOUS — Built-in cloud LLM providers. * * Sensible defaults for popular providers — all DISABLED by default per * ADR 0011 (Maximum Privacy Default). User opts in per provider in * Settings → AI Models → Cloud Providers. * * Built-in providers can be MODIFIED by the user (e.g., change default * model, add API key) but cannot be DELETED (user can only disable them). * * User-added providers (with [CloudProviderConfig.CUSTOM_PREFIX] ID) can * be fully added/edited/deleted by the user. * * ## Adding a New Built-in Provider * * When a new major provider launches in the market: *   1. Add a new entry to [ALL] below with sensible defaults *   2. Set `isBuiltIn = true` *   3. Set `isEnabled = false` (privacy default) *   4. Set pricing to current published rates *   5. Set certPins to the provider's published SPKI hashes * * No code change needed for user-added providers — they just call * [CloudProviderRegistry.addUserProvider] with their config. * * @see <a href="docs/adr/0011-maximum-privacy-default.md">ADR 0011</a> */object BuiltInCloudProviders {    /** OpenAI — GPT-4o, GPT-4o-mini, o1, o3, etc. */    val OPENAI = CloudProviderConfig(        id = "openai",        displayName = "OpenAI",        baseUrl = "https://api.openai.com/v1",        apiKeyAlias = "openai_api_key",        apiProtocol = ApiProtocol.OPENAI_COMPATIBLE,        defaultModel = "gpt-4o-mini",        availableModels = listOf(            "gpt-4o",            "gpt-4o-mini",            "o1",            "o1-mini",            "o3-mini",        ),        pricingPer1kTokens = Pricing.GPT_4O_MINI,  // default to cheapest        maxContextLength = 128_000,        timeoutMs = 60_000L,        isEnabled = false,        isBuiltIn = true,        certPins = listOf(            // Real pins to be added in Module 4 (security hardening) — placeholder for now            // "sha256/AAAA...=",        ),    )    /** Anthropic — Claude 3.5 Sonnet, Claude 3 Opus, etc. */    val ANTHROPIC = CloudProviderConfig(        id = "anthropic",        displayName = "Anthropic Claude",        baseUrl = "https://api.anthropic.com",        apiKeyAlias = "anthropic_api_key",        apiProtocol = ApiProtocol.ANTHROPIC,        defaultModel = "claude-3-5-sonnet-20241022",        availableModels = listOf(            "claude-3-5-sonnet-20241022",            "claude-3-5-haiku-20241022",            "claude-3-opus-20240229",        ),        pricingPer1kTokens = Pricing.CLAUDE_3_5_SONNET,        maxContextLength = 200_000,        timeoutMs = 60_000L,        isEnabled = false,        isBuiltIn = true,    )    /** Google Gemini — Gemini 1.5 Pro, Gemini 1.5 Flash, etc. */    val GEMINI = CloudProviderConfig(        id = "gemini",        displayName = "Google Gemini",        baseUrl = "https://generativelanguage.googleapis.com",        apiKeyAlias = "gemini_api_key",        apiProtocol = ApiProtocol.GEMINI,        defaultModel = "gemini-1.5-flash",        availableModels = listOf(            "gemini-1.5-pro",            "gemini-1.5-flash",            "gemini-1.5-flash-8b",        ),        pricingPer1kTokens = Pricing.GEMINI_1_5_FLASH,        maxContextLength = 1_000_000,        timeoutMs = 60_000L,        isEnabled = false,        isBuiltIn = true,    )    /** Groq — ultra-low-latency inference for open models. */    val GROQ = CloudProviderConfig(        id = "groq",        displayName = "Groq",        baseUrl = "https://api.groq.com/openai/v1",        apiKeyAlias = "groq_api_key",        apiProtocol = ApiProtocol.OPENAI_COMPATIBLE,        defaultModel = "llama-3.1-70b-versatile",        availableModels = listOf(            "llama-3.1-70b-versatile",            "llama-3.1-8b-instant",            "mixtral-8x7b-32768",            "gemma2-9b-it",        ),        pricingPer1kTokens = Pricing.GROQ_FREE,        maxContextLength = 128_000,        timeoutMs = 30_000L,        isEnabled = false,        isBuiltIn = true,    )    /** OpenRouter — unified gateway to 100+ models. */    val OPENROUTER = CloudProviderConfig(        id = "openrouter",        displayName = "OpenRouter",        baseUrl = "https://openrouter.ai/api/v1",        apiKeyAlias = "openrouter_api_key",        apiProtocol = ApiProtocol.OPENAI_COMPATIBLE,        defaultModel = "openai/gpt-4o-mini",        availableModels = listOf(            "openai/gpt-4o",            "openai/gpt-4o-mini",            "anthropic/claude-3.5-sonnet",            "google/gemini-flash-1.5",            "meta-llama/llama-3.1-70b-instruct",        ),        pricingPer1kTokens = Pricing.GPT_4O_MINI,  // varies per model        maxContextLength = 128_000,        timeoutMs = 60_000L,        isEnabled = false,        isBuiltIn = true,    )    /**     * All built-in providers, in display order.     *     * Order matters for UI — most popular first.     */    val ALL: List<CloudProviderConfig> = listOf(        OPENAI,        ANTHROPIC,        GEMINI,        GROQ,        OPENROUTER,    )    /**     * Look up a built-in provider by ID.     *     * @return the provider config, or null if not a built-in     */    fun byId(id: String): CloudProviderConfig? = ALL.find { it.id == id }    /**     * Whether [id] is a built-in provider ID.     */    fun isBuiltIn(id: String): Boolean = ALL.any { it.id == id }}